        await ev("""__mock.setPeers([{peer:'pa',by:'u_a',presence:{v:1,x:1.5,z:24.5,y:0,yaw:3.14,mv:0,col:'#2e9e6b',gt:0,sn:0,say:''}},{peer:'pb',by:'u_b',presence:{v:1,x:-2,z:23,y:0,yaw:1.2,mv:0,col:'#d08a2c',gt:0,sn:0,say:''}}])""")
        await pg.wait_for_timeout(500)
        await ev("""__mock.setPeers([{peer:'pa',by:'u_a',presence:{v:1,x:1.5,z:24.5,y:0,yaw:3.14,mv:0,col:'#2e9e6b',gt:0,sn:1,say:'You are an idiot'}},{peer:'pb',by:'u_b',presence:{v:1,x:-2,z:23,y:0,yaw:1.2,mv:0,col:'#d08a2c',gt:0,sn:0,say:''}}])""")
        await pg.wait_for_timeout(300)
        R['hereChip']=await ev("document.getElementById('here').textContent")
        await pg.click('#here'); await pg.wait_for_timeout(300)
        R['peopleRows']=await ev("[...document.querySelectorAll('#peopleList .prow .pn')].map(e=>e.textContent)")
        await pg.click('#peopleList .prow:has-text("Lina") button:has-text("Mute")'); await pg.wait_for_timeout(200)
        await ev("""__mock.setPeers([{peer:'pa',by:'u_a',presence:{v:1,x:1.5,z:24.5,y:0,yaw:3.14,mv:0,col:'#2e9e6b',gt:0,sn:2,say:'Still shouting'}},{peer:'pb',by:'u_b',presence:{v:1,x:-2,z:23,y:0,yaw:1.2,mv:0,col:'#d08a2c',gt:0,sn:0,say:''}}])""")
        await pg.wait_for_timeout(300)
