        R['mutedPersisted']=await ev("localStorage.getItem('ehc-muted')")
        await pg.click('#peopleList .prow:has-text("Lina") button:has-text("Report")'); await pg.wait_for_timeout(200)
        await pg.click('#reportSend'); R['reportNeedsReason']=await ev("document.getElementById('reportMsg').textContent")
        await pg.check('input[value="Harassment or bullying"]'); await pg.fill('#reportNote','Insulted me twice'); await pg.click('#reportSend'); await pg.wait_for_timeout(400)
        R['reportMsg']=await ev("document.getElementById('reportMsg').textContent")
        R['reportStored']=await ev("JSON.stringify(__store['reports/u_me'])")
        await pg.wait_for_timeout(1500)
        await ev("document.getElementById('here').click()"); await pg.wait_for_timeout(200)
        await pg.click('#peopleList .prow:has-text("Karim") button:has-text("Block")'); await pg.wait_for_timeout(200)
        R['afterBlock']=await ev("[__EHC.social.peers.size, [...__EHC.social.peers.values()].map(p=>p.name), document.getElementById('blockedBox').textContent]")
        await ev("__mock.setPeers([{peer:'pa',by:'u_a',presence:{v:1,x:1.5,z:24.5,y:0,yaw:3.14,mv:0,gt:0,sn:2,say:''}},{peer:'pb',by:'u_b',presence:{v:1,x:-2,z:23,y:0,yaw:1.2,mv:0,gt:0,sn:0,say:''}}])"); await pg.wait_for_timeout(300)
        R['blockedStaysHidden']=await ev("[...__EHC.social.peers.values()].map(p=>p.name)")
        await pg.click('#blockedBox button'); await pg.wait_for_timeout(200)
        await ev("__mock.setPeers([{peer:'pa',by:'u_a',presence:{v:1,x:1.5,z:24.5,y:0,yaw:3.14,mv:0,gt:0,sn:2,say:''}},{peer:'pb',by:'u_b',presence:{v:1,x:-2,z:23,y:0,yaw:1.2,mv:0,gt:0,sn:0,say:''}}])"); await pg.wait_for_timeout(300)
        R['afterUnblock']=await ev("__EHC.social.peers.size")
        await pg.click('#peopleClose')
        # chat panel moderation row
        await ev("__EHC.place(1.5,26,3.14); __EHC.setView(0,0.3,4)"); await pg.wait_for_timeout(300)
        R['preE']=await ev("[document.activeElement.tagName+'#'+document.activeElement.id, (__EHC.nearP||{}).label, [...document.querySelectorAll('.sheet:not([hidden])')].map(s=>s.id)]")
        await pg.keyboard.press('e'); await pg.wait_for_timeout(300)
        R['chatMod']=await ev("[...document.querySelectorAll('#cMod button')].map(b=>b.textContent)")
        R['chatTarget']=await ev("(()=>{const T=__EHC.social.target; return T&&[T.kind, T.ref.name||'', (__EHC.nearP||{}).label]})()")
        await pg.keyboard.press('Escape')
        # --- activity: visit a stand, open it, ask a question, take photo
        await ev("window.__EHC_HOLD=true")
        st=await ev("(()=>{const E=__EHC; const h=E.W.interact.find(h=>/booth-Gold/.test(h.id)); E.teleport('expo'); E.place(h.x+0.3,h.z+0.3); E.tick(60*6); return h.id})()")
        await ev(f"__EHC.openNear(); __EHC.closeSheets()")
        await ev("window.__EHC_HOLD=false; __EHC.team.event('question'); __EHC.team.saveNow()"); await pg.wait_for_timeout(300)
        R['analyticsDoc']=await ev("(()=>{const d=__store['analytics/u_me']; return d&&{named:d.named,name:d.name,stand:d.stands[%s],zones:Object.keys(d.zones),questions:d.questions,sessions:d.sessions}})()" % json.dumps(st))
        # second attendee (anonymous) in the store, then the owner report
        await ev("""__store['analytics/u_x']={v:1,uid:'u_x',named:false,name:'',sessions:2,zones:{expo:300,foyer:120},questions:{expo:3},stands:{%s:{visits:2,sec:90,opens:1}}}; __store['analytics/u_evil']={uid:'u_evil',named:true,name:'=HYPERLINK("http://x")',stands:{%s:{visits:1,sec:5,opens:0}},zones:{expo:'<img src=x onerror=window.__p=1>'}}""" % (json.dumps(st),json.dumps(st)))
        await pg.click('#bTeam'); await pg.wait_for_timeout(500)
        R['activitySummary']=await ev("document.querySelector('#tActivity p').textContent")
        R['standRow']=await ev("[...document.querySelectorAll('#tActivity table')][0]?.querySelector('tbody tr')?.textContent")
        await pg.click('#tActivity button:has-text("named visitors")'); await pg.wait_for_timeout(300)
        R['csv']=await ev("__EHC.team.lastDownload")
        R['csvSafe']=await ev("__EHC.team.csv(['a'],[['=HYPERLINK(1)']])")
        await pg.screenshot(path='tests/out/shots/t_activity.png')
        await pg.click('[data-tteam=reports]'); await pg.wait_for_timeout(300)
        R['reportsTab']=await ev("[...document.querySelectorAll('#tReports .rcard')].map(e=>e.textContent.slice(0,120))")
        await pg.click('[data-tteam=screens]'); await pg.wait_for_timeout(200)
        R['screensTab']=await ev("[...document.querySelectorAll('#tScreens .prow')].map(e=>e.textContent)")
        await pg.click('#teamClose')
        R['noInjection']=await ev("!window.__p")
        # --- screen recording plays near the plenary screen
        await ev("__EHC.teleport('plenary'); __EHC.place(0,-30,3.14)"); await pg.wait_for_timeout(9000)
        R['videoFrames']=await ev("__EHC.team.framesDrawn||0")
        R['badUrlsIgnored']=await ev("Object.keys(__EHC.team.screenMap)")
        await pg.screenshot(path='tests/out/shots/t_screen_video.png')
        R['errors']=logs
        await pg.context.close()
        # --- view-only visitor: db writes refused
        pg,logs=await page(b,{'sample':'ok','room':True,'owner':False,'dbDeny':True})
        await pg.evaluate('__EHC.enter()'); await pg.wait_for_timeout(400)
        R['viewer_teamBtnHidden']=await pg.evaluate("document.getElementById('bTeam').hidden")
        await pg.evaluate("__EHC.team.dirty=true; return __EHC.team.saveNow()") if False else await pg.evaluate("(async()=>{__EHC.team.dirty=true; await __EHC.team.saveNow(); return 1})()")
        R['viewer_canWrite']=await pg.evaluate("__EHC.team.canWrite")
        await pg.evaluate("""__mock.setPeers([{peer:'pa',by:'u_a',presence:{v:1,x:1.5,z:24.5,y:0,yaw:3.14,mv:0,gt:0,sn:0,say:''}}])"""); await pg.wait_for_timeout(300)
        await pg.evaluate("__EHC.team.openReport([...__EHC.social.peers.values()][0])"); await pg.check('input[value="Spam or selling"]'); await pg.click('#reportSend'); await pg.wait_for_timeout(300)
        R['viewer_reportMsg']=await pg.evaluate("document.getElementById('reportMsg').textContent")
        R['viewer_errors']=logs
        await pg.context.close()
        # --- device check (desktop, quick)
        pg,logs=await page(b,{'sample':'ok','room':False})
        await pg.evaluate('__EHC.enter()'); await pg.wait_for_timeout(300)
        await pg.evaluate("document.getElementById('bAgenda').click()"); await pg.wait_for_timeout(200)
        await pg.click('#bCheck2'); await pg.wait_for_function("__EHC.team.lastCheck",timeout=120000)
        R['check']=await pg.evaluate("(()=>{const c=__EHC.team.lastCheck; return {verdict:c.verdict, avg:c.averageFps, areas:c.results.length, action:c.action, title:document.getElementById('checkTitle').textContent, backInFoyer:__EHC.zone}})()")
        await pg.screenshot(path='tests/out/shots/t_check.png')
        await pg.click('#checkSave'); await pg.wait_for_timeout(300); R['checkDownload']=await pg.evaluate("__EHC.team.lastDownload")
        R['check_errors']=logs
        await pg.context.close()
        # --- mobile layout of new sheets
